        keyABContainer.style.display = "flex"
        keyABContainer.style.gap = "10px"
        keyABContainer.style.padding = "10px"
        keyABContainer.style.zIndex = "99999"

        var keyA = document.createElement("div")
        keyA.innerText = "A"
        keyA.style.width = isSmallScreen ? "70px" : "90px"
        keyA.style.height = isSmallScreen ? "70px" : "90px"
        keyA.style.backgroundColor = "rgba(0,0,0,0.25)"
        keyA.style.border = "1px solid rgba(255,255,255,0.2)"
        keyA.style.fontFamily = "Arial"
        keyA.style.fontSize = isSmallScreen ? "40px" : "50px"
        keyA.style.display = "flex"
        keyA.style.alignItems = "center"
        keyA.style.justifyContent = "center"
        keyA.style.color = "rgba(255,255,255,0.3)"
